        ["give.sec.params"] = ("What each value is", "Что означает каждое значение"),
        ["give.unit"] = ("Scene unit", "Единица сцены"),
        ["give.unit.mm"] = ("1 unit = 1 mm", "1 единица = 1 мм"),
