        ["give.unit.m"] = ("1 unit = 1 m", "1 единица = 1 м"),
        ["give.fig.rgb"] = ("n at 610, 550, 465 nm", "n на 610, 550, 465 нм"),
        ["give.fig.face"] = ("reflected head-on", "отражается при прямом взгляде"),
        ["give.fig.tint"] = ("daylight after {0} mm", "дневной свет после {0} мм"),
        ["give.fig.y"] = ("of the light gets through", "света проходит"),
        ["give.p.tint"] = ("Tint", "Оттенок"),
        ["give.p.luminance"] = ("Luminous transmittance", "Световое пропускание"),
        ["give.p.face"] = ("Face reflectance", "Отражение лица"),
