        ["give.p.critical"] = ("Critical angle", "Критический угол"),
        ["give.x.tint"] = ("the colour of D65 daylight after the chosen thickness, integrated from the glass's k table with the CIE 1931 observer and companded to sRGB.", "цвет дневного света D65 после выбранной толщины, проинтегрированный из таблицы k стекла с наблюдателем CIE 1931 и переведённый в sRGB."),
        ["give.x.luminance"] = ("the share of visible light that gets through that thickness (Y of the same integration). The fill opacity in CSS and Figma is 1 − Y plus a small floor so a clear glass still reads as present.", "доля видимого света, прошедшего эту толщину (Y того же интеграла). Непрозрачность заливки в CSS и Figma — это 1 − Y плюс небольшой минимум, чтобы прозрачное стекло всё же читалось."),
        ["give.x.face"] = ("Fresnel reflectance at normal incidence, ((n−1)/(n+1))². It sets the strength of the top highlight; a crown returns about 4%, a dense flint almost 8%.", "френелевское отражение при нормальном падении, ((n−1)/(n+1))². Задаёт силу верхнего блика; крон возвращает около 4%, плотный флинт почти 8%."),
        ["give.x.edge"] = ("exact unpolarized Fresnel reflectance at 60°, the slope of a bevel. It sets the stroke opacity: the rim of a glass is brighter than its face.", "точное неполяризованное отражение Френеля под 60°, наклон фаски. Задаёт непрозрачность обводки: край стекла ярче лица."),
        ["give.x.frost"] = ("a blur radius. Not a property of the glass; real frosted glass is a rough surface that scatters. Keep it as a design decision.", "радиус размытия. Не свойство стекла: настоящее матовое стекло — шероховатая поверхность, которая рассеивает. Оставь это решением дизайнера."),
        ["give.x.rgb"] = ("the dispersion curve sampled at 610, 550 and 465 nm, one index per colour channel. Refracting each channel with its own index is what produces colour fringes.", "кривая дисперсии в точках 610, 550 и 465 нм, по показателю на канал. Преломление каждого канала своим показателем и даёт цветные каймы."),
        ["give.x.alpha"] = ("Beer–Lambert absorption coefficient per metre from the tabulated k: α = 4πk/λ. Transmittance over a path d is exp(−α·d). Zero means the catalog has no k table for this glass.", "коэффициент поглощения Бера–Ламберта на метр из табличного k: α = 4πk/λ. Пропускание на пути d равно exp(−α·d). Ноль означает, что таблицы k для стекла в каталоге нет."),
        ["give.x.thickness"] = ("the path the ray travels inside, in millimetres, before absorption is applied. Everything scales with it: keep it in real units.", "путь луча внутри в миллиметрах до применения поглощения. С ней масштабируется всё: держи её в реальных единицах."),
        ["give.x.critical"] = ("asin(1/n): inside the glass, rays steeper than this reflect totally instead of leaving. That reflection is what makes prisms and gems bright inside.", "asin(1/n): внутри стекла лучи круче этого угла полностью отражаются, а не выходят. Это отражение и делает призмы и камни яркими внутри."),
        ["give.x.ior"] = ("n<sub>d</sub>, the index at the helium d line (587.6 nm), the value every physically based material calls IOR.", "n<sub>d</sub>, показатель на линии d гелия (587,6 нм), то, что каждый физически корректный материал называет IOR."),
        ["give.x.abbe"] = ("ν<sub>d</sub> = (n<sub>d</sub> − 1)/(n<sub>F</sub> − n<sub>C</sub>). Lower means stronger dispersion; Blender takes it directly with Dispersion Scale at 1.", "ν<sub>d</sub> = (n<sub>d</sub> − 1)/(n<sub>F</sub> − n<sub>C</sub>). Чем ниже, тем сильнее дисперсия; Blender берёт его напрямую при Dispersion Scale 1."),
        ["give.x.dispersion20"] = ("KHR_materials_dispersion stores 20 divided by the Abbe number, so 1.0 is about the most dispersive glass there is and 0.3 is a crown.", "KHR_materials_dispersion хранит 20, делённое на число Аббе: 1,0 — примерно самое дисперсионное стекло, 0,3 — крон."),
        ["give.x.attcolour"] = ("what white light becomes after the attenuation distance: exp(−α·distance) per channel, linear RGB. It reproduces the k table exactly at that distance and follows Beer–Lambert elsewhere.", "во что превращается белый свет после расстояния затухания: exp(−α·расстояние) по каналам, линейный RGB. На этом расстоянии воспроизводит таблицу k точно, дальше следует Беру–Ламберту."),
        ["give.x.attdistance"] = ("the distance the colour above is stated for, in scene units. Set it to the wall thickness and the colour becomes the exact transmittance of that wall.", "расстояние, для которого указан цвет выше, в единицах сцены. Поставь толщину стенки, и цвет станет точным пропусканием этой стенки."),
        ["give.x.thicknessunits"] = ("the volume's thickness in mesh units, used to scale the refraction and the absorption path.", "толщина объёма в единицах меша, масштабирует преломление и путь поглощения."),
        ["give.x.density"] = ("Cycles absorbs at Density × (1 − Color) per channel and per scene unit. Density is set to the largest of the three α so that every channel's colour stays within 0–1.", "Cycles поглощает с силой Density × (1 − Color) по каналам на единицу сцены. Density равна наибольшей из трёх α, чтобы цвет каждого канала остался в 0–1."),
        ["give.x.blendercolour"] = ("1 − α<sub>c</sub>/Density per channel: together with Density it reproduces the three absorption coefficients exactly, not a colour picked by eye.", "1 − α<sub>c</sub>/Density по каналам: вместе с Density воспроизводит три коэффициента поглощения точно, а не цвет, подобранный на глаз."),
        ["give.x.unrealspecular"] = ("Unreal's Specular pin is F0/0.08, with 0.5 meaning 4% reflectance head-on. The value here is the exact Fresnel F0 of this glass divided by 0.08.", "пин Specular в Unreal равен F0/0,08, где 0,5 означает 4% отражения при прямом взгляде. Здесь точное френелевское F0 этого стекла, делённое на 0,08."),
        ["give.x.roughness"] = ("polished optical glass is roughness 0; the catalog has no surface finish, so any other value is a design choice.", "полированное оптическое стекло — roughness 0; в каталоге нет обработки поверхности, любое другое значение — выбор дизайнера."),
        ["give.x.nd"] = ("the index at the d line and the Abbe number, checked at build time against the printed datasheet values.", "показатель на линии d и число Аббе, сверенные при сборке с печатными значениями даташита."),
        ["give.x.extinction"] = ("the wavelength range of the tabulated k, from which InternalTransmittance and AbsorptionCoefficient are computed.", "диапазон длин волн табличного k, из которого считаются InternalTransmittance и AbsorptionCoefficient."),
        ["give.x.thermal"] = ("the manufacturer's dn/dT formula, when the datasheet gives one; AbsoluteIndexShift applies it.", "формула dn/dT производителя, когда даташит её даёт; AbsoluteIndexShift её применяет."),
        ["give.x.thermal.yes"] = ("dn/dT available", "dn/dT есть"),
        ["give.x.provenance"] = ("where every number came from: the database path, the commit and the citation.", "откуда каждое число: путь в базе, коммит и цитата."),
        ["give.fmt.css.p"] = ("Custom properties and a class. The tint, the luminance and the two Fresnel numbers are this glass; the blur is a design choice. CSS cannot refract, so the bend and the fringes live only in the shader tab.", "Кастомные свойства и класс. Оттенок, пропускание и два числа Френеля — это стекло; размытие — выбор дизайнера. CSS не умеет преломлять, поэтому излом и каймы живут только на вкладке шейдера."),
        ["give.fmt.tailwind.p"] = ("The same numbers as arbitrary values in utility classes.", "Те же числа как произвольные значения в утилитарных классах."),
        ["give.fmt.figma.p"] = ("Values to type into Figma's fill, stroke and effects panels for a panel of this glass.", "Значения для панелей заливки, обводки и эффектов Figma для панели из этого стекла."),
        ["give.fmt.glsl.p"] = ("The constants a UI glass shader needs. The Design page renders the whole panel with them and hands out the full shader.", "Константы, которые нужны шейдеру UI-стекла. Страница Design рисует ими всю панель и отдаёт полный шейдер."),
        ["give.fmt.hlsl.p"] = ("Engine-agnostic functions that compile as HLSL and GLSL: exact Fresnel and one channel through a slab, with this glass's constants.", "Функции без привязки к движку, компилируются как HLSL и GLSL: точный Френель и один канал через пластину, с константами этого стекла."),
        ["give.fmt.unity.p"] = ("HDRP's Lit material takes an index, a transmittance colour and an absorption distance; the last two are the glTF volume model, so the numbers are exact for the wall thickness. Dispersion needs the custom HLSL.", "Материал Lit в HDRP берёт показатель, цвет пропускания и расстояние поглощения; последние два — модель объёма glTF, поэтому числа точны для толщины стенки. Дисперсия требует своего HLSL."),
        ["give.fmt.unreal.p"] = ("Unreal's translucent material takes the index on the Refraction pin and Fresnel head-on through Specular; absorption and dispersion go into a Custom node with the HLSL functions.", "Полупрозрачный материал Unreal берёт показатель на пин Refraction и Френель при прямом взгляде через Specular; поглощение и дисперсия идут в узел Custom с функциями HLSL."),
        ["give.fmt.godot.p"] = ("A complete Godot 4 spatial shader: the screen behind the surface refracted per channel, exact Fresnel, Beer–Lambert absorption over the path.", "Полный spatial-шейдер Godot 4: экран за поверхностью преломляется по каналам, точный Френель, поглощение Бера–Ламберта по пути."),
        ["give.fmt.blender.p"] = ("Values for the Principled BSDF and a Volume Absorption node, with the density given in three scene units. Dispersion renders in Cycles only.", "Значения для Principled BSDF и узла Volume Absorption, плотность дана в трёх единицах сцены. Дисперсия считается только в Cycles."),
        ["give.fmt.gltf.p"] = ("A glTF material with the transmission, ior, dispersion and volume extensions; any viewer that supports them shows this glass.", "Материал glTF с расширениями transmission, ior, dispersion и volume; любой просмотрщик с их поддержкой покажет это стекло."),
        ["give.fmt.usd.p"] = ("UsdPreviewSurface carries the index and nothing else about glass; for absorption and dispersion the renderer's own schema is needed.", "UsdPreviewSurface несёт показатель и больше ничего о стекле; для поглощения и дисперсии нужна схема конкретного рендера."),
        ["give.fmt.threejs.p"] = ("MeshPhysicalMaterial with transmission, ior, dispersion and the volume attenuation. three.js clamps ior to 2.333, which no catalog glass exceeds.", "MeshPhysicalMaterial с transmission, ior, dispersion и затуханием объёма. three.js ограничивает ior значением 2,333, которого ни одно стекло каталога не превышает."),
        ["give.fmt.csray.p"] = ("The ray path: the typed constant evaluates the curve, Dielectric splits the ray at the surface.", "Путь луча: типизированная константа считает кривую, Dielectric делит луч на поверхности."),
        ["give.fmt.cscolour.p"] = ("Colour and absorption from the k table, integrated against D65 and the CIE observer.", "Цвет и поглощение из таблицы k, проинтегрированные по D65 и наблюдателю CIE."),
        ["give.fmt.csthermal.p"] = ("The temperature and medium corrections a tolerance study needs.", "Поправки на температуру и среду, которые нужны расчёту допусков."),
        ["give.fmt.cscatalog.p"] = ("Searching the catalog and reading provenance.", "Поиск по каталогу и чтение источника."),
        ["give.fmt.csray.name"] = ("C#, ray", "C#, луч"),
        ["give.fmt.cscolour.name"] = ("C#, colour", "C#, цвет"),
        ["give.fmt.csthermal.name"] = ("C#, temperature", "C#, температура"),
